package main

import (
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"math/rand"
	"os"
)

// The user's exact algorithm, with the seed passed in explicitly.
func eatingHash(seed uint64, bytes []byte) uint64 {
	length := len(bytes)
	rmd := length
	s := seed ^ 0xCAFECAFECAFECAFE
	h := s
	i := 0
	for ; rmd >= 16; i += 16 {
		h ^= binary.LittleEndian.Uint64(bytes[i : i+8])
		h *= 0xBABEBEEFBABEBEEF
		h ^= h >> 33
		h *= 0xF00DF00DF00DF00D
		h ^= h >> 29
		h ^= binary.LittleEndian.Uint64(bytes[i+8 : i+16])
		h *= 0xBABEBEEFBABEBEEF
		h ^= h >> 33
		h *= 0xF00DF00DF00DF00D
		h ^= h >> 29
		rmd -= 16
	}
	for ; rmd >= 8; i += 8 {
		h ^= binary.LittleEndian.Uint64(bytes[i : i+8])
		h *= 0xBABEBEEFBABEBEEF
		h ^= h >> 33
		h *= 0xF00DF00DF00DF00D
		h ^= h >> 29
		rmd -= 8
	}
	var tail uint64 = 0
	switch rmd {
	case 7:
		tail |= uint64(bytes[i+6]) << 48
		fallthrough
	case 6:
		tail |= uint64(bytes[i+5]) << 40
		fallthrough
	case 5:
		tail |= uint64(bytes[i+4]) << 32
		fallthrough
	case 4:
		tail |= uint64(bytes[i+3]) << 24
		fallthrough
	case 3:
		tail |= uint64(bytes[i+2]) << 16
		fallthrough
	case 2:
		tail |= uint64(bytes[i+1]) << 8
		fallthrough
	case 1:
		tail |= uint64(bytes[i])
	}
	h ^= tail
	h *= 0xBABEBEEFBABEBEEF
	h ^= h >> 33
	h *= 0xF00DF00DF00DF00D
	h ^= h >> 29
	h ^= uint64(length) * 0xBABEBEEFBABEBEEF
	h ^= s * 0xF00DF00DF00DF00D
	h *= 0xBABEBEEFBABEBEEF
	h ^= h >> 33
	h *= 0xF00DF00DF00DF00D
	h ^= h >> 29
	h *= 0xBABEBEEFF00DF00D
	h ^= h >> 31
	return h
}

func main() {
	out, err := os.Create(os.Args[1])
	if err != nil {
		panic(err)
	}
	defer out.Close()

	rng := rand.New(rand.NewSource(20261007))

	type tc struct {
		seed uint64
		data []byte
	}
	var cases []tc

	// Deterministic structured cases
	seeds := []uint64{0, 1, 0xCAFECAFECAFECAFE, 0x0123456789ABCDEF, 0xFFFFFFFFFFFFFFFF, 0xDEADBEEF}
	for _, s := range seeds {
		for l := 0; l <= 40; l++ {
			d := make([]byte, l)
			for j := range d {
				d[j] = byte(j)
			}
			cases = append(cases, tc{s, d})
		}
		// all-zero and all-ff buffers
		for _, fill := range []byte{0x00, 0xFF} {
			for _, l := range []int{0, 1, 7, 8, 15, 16, 17, 24, 31, 32, 33, 64, 100, 255, 256, 1000} {
				d := make([]byte, l)
				for j := range d {
					d[j] = fill
				}
				cases = append(cases, tc{s, d})
			}
		}
	}

	// Random cases across many lengths
	for n := 0; n < 4000; n++ {
		l := rng.Intn(300)
		d := make([]byte, l)
		rng.Read(d)
		cases = append(cases, tc{rng.Uint64(), d})
	}

	// A few long inputs
	for n := 0; n < 20; n++ {
		l := rng.Intn(5000) + 1000
		d := make([]byte, l)
		rng.Read(d)
		cases = append(cases, tc{rng.Uint64(), d})
	}

	for _, c := range cases {
		h := eatingHash(c.seed, c.data)
		fmt.Fprintf(out, "%016x %d %s %016x\n", c.seed, len(c.data), hex.EncodeToString(c.data), h)
	}
	fmt.Printf("wrote %d vectors\n", len(cases))
}

