// Load-factor sensitivity benchmark for eatingHash vs a reference mixer.
// Compares plain linear probing vs Swiss-style group(8) probing at
// load factors 50% / 62.5% / 75% / 87.5%, with and without tombstones.
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <chrono>
#include <vector>
#include <random>
#include <algorithm>

// ---------------- hashes ----------------
static const uint64_t C1 = UINT64_C(0xBABEBEEFBABEBEEF);
static const uint64_t C2 = UINT64_C(0xF00DF00DF00DF00D);
static const uint64_t C3 = UINT64_C(0xBABEBEEFF00DF00D);
static const uint64_t SEED_XOR = UINT64_C(0xCAFECAFECAFECAFE);

static inline uint64_t eating_mix(uint64_t h, uint64_t w) {
    h ^= w; h *= C1; h ^= h >> 33; h *= C2; h ^= h >> 29; return h;
}
static uint64_t eatingHash(const uint8_t * buf, size_t len, uint64_t seed) {
    size_t rmd = len, i = 0;
    const uint64_t s = seed ^ SEED_XOR;
    uint64_t h = s;
    for (; rmd >= 16; i += 16, rmd -= 16) {
        uint64_t a, b; memcpy(&a, buf + i, 8); memcpy(&b, buf + i + 8, 8);
        h = eating_mix(h, a); h = eating_mix(h, b);
    }
    for (; rmd >= 8; i += 8, rmd -= 8) {
        uint64_t a; memcpy(&a, buf + i, 8); h = eating_mix(h, a);
    }
    uint64_t tail = 0;
    for (size_t j = 0; j < rmd; j++) tail |= (uint64_t)buf[i + j] << (8 * j);
    h = eating_mix(h, tail);
    h ^= (uint64_t)len * C1; h ^= s * C2;
    h *= C1; h ^= h >> 33; h *= C2; h ^= h >> 29; h *= C3; h ^= h >> 31;
    return h;
}
// reference: splitmix64-style strong finalizer over the same bytes
static uint64_t refHash(const uint8_t * buf, size_t len, uint64_t seed) {
    uint64_t h = seed ^ UINT64_C(0x9E3779B97F4A7C15) ^ len;
    size_t i = 0;
    for (; i + 8 <= len; i += 8) {
        uint64_t a; memcpy(&a, buf + i, 8);
        h ^= a + UINT64_C(0x9E3779B97F4A7C15);
        h = (h ^ (h >> 30)) * UINT64_C(0xBF58476D1CE4E5B9);
        h = (h ^ (h >> 27)) * UINT64_C(0x94D049BB133111EB);
    }
    uint64_t tail = 0;
    for (size_t j = 0; i + j < len; j++) tail |= (uint64_t)buf[i + j] << (8 * j);
    h ^= tail + UINT64_C(0x9E3779B97F4A7C15);
    h = (h ^ (h >> 30)) * UINT64_C(0xBF58476D1CE4E5B9);
    h = (h ^ (h >> 27)) * UINT64_C(0x94D049BB133111EB);
    return h ^ (h >> 31);
}

using HashFn = uint64_t (*)(const uint8_t *, size_t, uint64_t);

// ---------------- tables ----------------
// state: 0 = empty, 1 = occupied, 2 = tombstone
struct LinearTable {
    std::vector<uint64_t> keys;
    std::vector<uint8_t>  st;
    std::vector<uint8_t>  kbuf;  // full key bytes
    size_t ksz, mask, size = 0, tombs = 0;
    HashFn hash;

    void init(size_t cap, size_t ksz_, HashFn h) {
        while (cap & (cap - 1)) cap++;  // pow2
        keys.resize(cap); st.assign(cap, 0);
        ksz = ksz_; kbuf.assign(cap * ksz, 0);
        mask = cap - 1; hash = h; size = tombs = 0;
    }
    inline uint64_t hk(const uint8_t * k) const { return hash(k, ksz, 0); }

    bool insert(const uint8_t * k) {
        uint64_t h = hk(k);
        size_t p = h & mask;
        size_t first_tomb = (size_t)-1;
        for (;;) {
            if (st[p] == 0) {
                size_t q = (first_tomb != (size_t)-1) ? first_tomb : p;
                if (q != p && first_tomb != (size_t)-1) tombs--;
                memcpy(&kbuf[q * ksz], k, ksz);
                keys[q] = h; st[q] = 1; size++;
                return true;
            }
            if (st[p] == 2) { if (first_tomb == (size_t)-1) first_tomb = p; }
            else if (keys[p] == h && memcmp(&kbuf[p * ksz], k, ksz) == 0) return false;
            p = (p + 1) & mask;
        }
    }
    // returns probe count
    size_t find(const uint8_t * k) const {
        uint64_t h = hk(k);
        size_t p = h & mask, probes = 1;
        for (;;) {
            if (st[p] == 0) return probes;
            if (st[p] == 1 && keys[p] == h && memcmp(&kbuf[p * ksz], k, ksz) == 0) return probes;
            p = (p + 1) & mask; probes++;
        }
    }
    void del(const uint8_t * k) {
        uint64_t h = hk(k);
        size_t p = h & mask;
        for (;;) {
            if (st[p] == 0) return;
            if (st[p] == 1 && keys[p] == h && memcmp(&kbuf[p * ksz], k, ksz) == 0) {
                st[p] = 2; size--; tombs++; return;
            }
            p = (p + 1) & mask;
        }
    }
};

// Swiss-ish: groups of 8 control bytes, bitmask match, hop by group
struct SwissTable {
    std::vector<uint64_t> keys;
    std::vector<uint8_t>  ctrl;  // 0 = empty, 1 = tomb, 2..255 = h2+2
    std::vector<uint8_t>  kbuf;
    size_t ksz, mask, size = 0, tombs = 0;
    HashFn hash;

    void init(size_t cap, size_t ksz_, HashFn h) {
        while (cap & (cap - 1)) cap++;
        if (cap < 16) cap = 16;
        keys.resize(cap); ctrl.assign(cap, 0);
        ksz = ksz_; kbuf.assign(cap * ksz, 0);
        mask = cap - 1; hash = h; size = tombs = 0;
    }
    inline uint64_t hk(const uint8_t * k) const { return hash(k, ksz, 0); }
    static inline uint64_t splat(uint8_t b) { return UINT64_C(0x0101010101010101) * b; }
    static inline uint64_t match(uint64_t g, uint8_t b) {
        uint64_t x = g ^ splat(b);
        return (x - splat(1)) & ~x & splat(0x80);
    }
    inline uint64_t group(size_t p) const {
        uint64_t g = 0;
        for (int i = 0; i < 8; i++) g |= (uint64_t)ctrl[(p + i) & mask] << (8 * i);
        return g;
    }

    bool insert(const uint8_t * k) {
        uint64_t h = hk(k);
        uint8_t h2 = (uint8_t)((h >> 57) | 2);
        size_t p = h & mask;
        size_t first_tomb = (size_t)-1;
        for (;;) {
            uint64_t g = group(p);
            uint64_t m = match(g, h2);
            while (m) {
                int i = __builtin_ctzll(m) / 8;
                size_t q = (p + i) & mask;
                if (keys[q] == h && memcmp(&kbuf[q * ksz], k, ksz) == 0) return false;
                m &= m - 1;
            }
            uint64_t e = match(g, 0);
            if (e) {
                int i = __builtin_ctzll(e) / 8;
                size_t q = (p + i) & mask;
                if (first_tomb != (size_t)-1) { q = first_tomb; tombs--; }
                memcpy(&kbuf[q * ksz], k, ksz);
                keys[q] = h; ctrl[q] = h2; size++;
                return true;
            }
            if (first_tomb == (size_t)-1) {
                uint64_t t = match(g, 1);
                if (t) first_tomb = (p + __builtin_ctzll(t) / 8) & mask;
            }
            p = (p + 8) & mask;
        }
    }
    size_t find(const uint8_t * k) const {
        uint64_t h = hk(k);
        uint8_t h2 = (uint8_t)((h >> 57) | 2);
        size_t p = h & mask, probes = 1;
        for (;;) {
            uint64_t g = group(p);
            uint64_t m = match(g, h2);
            while (m) {
                int i = __builtin_ctzll(m) / 8;
                size_t q = (p + i) & mask;
                if (keys[q] == h && memcmp(&kbuf[q * ksz], k, ksz) == 0) return probes;
                m &= m - 1;
            }
            if (match(g, 0)) return probes;
            p = (p + 8) & mask; probes++;
        }
    }
    void del(const uint8_t * k) {
        uint64_t h = hk(k);
        uint8_t h2 = (uint8_t)((h >> 57) | 2);
        size_t p = h & mask;
        for (;;) {
            uint64_t g = group(p);
            uint64_t m = match(g, h2);
            while (m) {
                int i = __builtin_ctzll(m) / 8;
                size_t q = (p + i) & mask;
                if (keys[q] == h && memcmp(&kbuf[q * ksz], k, ksz) == 0) {
                    ctrl[q] = 1; size--; tombs++; return;
                }
                m &= m - 1;
            }
            if (match(g, 0)) return;
            p = (p + 8) & mask;
        }
    }
};

// ---------------- bench ----------------
template <typename T>
static void bench(const char * tname, const char * hname, HashFn hash, size_t ksz,
                  double load, bool withtombs, const std::vector<uint8_t> & allkeys,
                  size_t nkeys) {
    size_t live = nkeys;
    size_t tombs = withtombs ? (size_t)(nkeys / 2) : 0;  // tombs = 50% of live
    size_t cap = (size_t)((live + tombs) / load);
    T t; t.init(cap, ksz, hash);

    for (size_t i = 0; i < live; i++) t.insert(&allkeys[i * ksz]);
    if (tombs) {
        // delete every other one of the first tombs*2 keys -> creates tombs
        for (size_t i = 0; i < tombs; i++) t.del(&allkeys[(2 * i) * ksz]);
    }

    // successful lookups
    std::vector<size_t> order(live);
    for (size_t i = 0; i < live; i++) order[i] = (i * 7919) % live;

    size_t probes_ok = 0, probes_no = 0;
    volatile uint64_t sink = 0;

    auto t0 = std::chrono::steady_clock::now();
    for (size_t r = 0; r < 3; r++)
        for (size_t i = 0; i < live; i++) {
            size_t idx = order[i];
            // skip deleted keys for successful lookup
            size_t pr = t.find(&allkeys[idx * ksz]);
            probes_ok += pr;
            sink += pr;
        }
    auto t1 = std::chrono::steady_clock::now();
    double ns_ok = std::chrono::duration<double, std::nano>(t1 - t0).count() / (3.0 * live);

    // unsuccessful lookups (keys not in table)
    std::vector<uint8_t> miss(ksz);
    std::mt19937_64 rng(12345);
    size_t nmiss = live;
    t0 = std::chrono::steady_clock::now();
    for (size_t r = 0; r < 3; r++)
        for (size_t i = 0; i < nmiss; i++) {
            for (size_t j = 0; j < ksz; j++) miss[j] = (uint8_t)rng();
            size_t pr = t.find(miss.data());
            probes_no += pr;
            sink += pr;
        }
    t1 = std::chrono::steady_clock::now();
    double ns_no = std::chrono::duration<double, std::nano>(t1 - t0).count() / (3.0 * nmiss);

    printf("%-8s %-9s %4.1f%% %s live=%zu tombs=%zu cap=%zu | "
           "ok: %5.2f probes %6.1f ns | miss: %6.2f probes %6.1f ns\n",
           tname, hname, load * 100, withtombs ? "w/tombs" : "clean ",
           t.size, t.tombs, t.mask + 1,
           (double)probes_ok / (3.0 * live), ns_ok,
           (double)probes_no / (3.0 * nmiss), ns_no);
}

int main() {
    const size_t N = 1 << 19;  // 524288 keys
    std::mt19937_64 rng(20261007);

    for (size_t ksz : { (size_t)8, (size_t)24 }) {
        std::vector<uint8_t> keys(N * ksz);
        for (auto & b : keys) b = (uint8_t)rng();
        printf("\n===== key size %zu bytes, %zu keys =====\n", ksz, N);
        printf("table    hash     load  state   occupancy                     ok-lookup              miss-lookup\n");
        for (double lf : { 0.50, 0.625, 0.75, 0.875 }) {
            for (int wt = 0; wt < 2; wt++) {
                bench<LinearTable>("linear", "eating", eatingHash, ksz, lf, wt, keys, N);
                bench<SwissTable>("swiss8", "eating", eatingHash, ksz, lf, wt, keys, N);
                bench<SwissTable>("swiss8", "splitmix", refHash, ksz, lf, wt, keys, N);
            }
        }
    }
    return 0;
}

// No-SIMD performance techniques for hash tables, measured with eatingHash.
// Variants:
//   linear      - plain linear probing (baseline, stores full hash)
//   linear+pf   - linear probing + software prefetch ahead
//   robinhood   - Robin Hood probing + backward-shift deletion (no tombstones)
//   swiss8-old  - group-of-8 ctrl matching, scalar byte loads (previous bench)
//   swiss8-swar - group-of-8 ctrl matching, single aligned 64-bit SWAR load
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <chrono>
#include <vector>
#include <random>

// ---------------- hashes ----------------
static const uint64_t C1 = UINT64_C(0xBABEBEEFBABEBEEF);
static const uint64_t C2 = UINT64_C(0xF00DF00DF00DF00D);
static const uint64_t C3 = UINT64_C(0xBABEBEEFF00DF00D);
static const uint64_t SEED_XOR = UINT64_C(0xCAFECAFECAFECAFE);

static inline uint64_t eating_mix(uint64_t h, uint64_t w) {
    h ^= w; h *= C1; h ^= h >> 33; h *= C2; h ^= h >> 29; return h;
}
static uint64_t eatingHash(const uint8_t * buf, size_t len, uint64_t seed) {
    size_t rmd = len, i = 0;
    const uint64_t s = seed ^ SEED_XOR;
    uint64_t h = s;
    for (; rmd >= 16; i += 16, rmd -= 16) {
        uint64_t a, b; memcpy(&a, buf + i, 8); memcpy(&b, buf + i + 8, 8);
        h = eating_mix(h, a); h = eating_mix(h, b);
    }
    for (; rmd >= 8; i += 8, rmd -= 8) {
        uint64_t a; memcpy(&a, buf + i, 8); h = eating_mix(h, a);
    }
    uint64_t tail = 0;
    for (size_t j = 0; j < rmd; j++) tail |= (uint64_t)buf[i + j] << (8 * j);
    h = eating_mix(h, tail);
    h ^= (uint64_t)len * C1; h ^= s * C2;
    h *= C1; h ^= h >> 33; h *= C2; h ^= h >> 29; h *= C3; h ^= h >> 31;
    return h;
}

// ---------------- shared storage ----------------
struct Store {
    std::vector<uint64_t> keys;   // full hash per slot
    std::vector<uint8_t>  kbuf;   // key bytes per slot
    size_t ksz = 0, cap = 0, mask = 0;
    void init(size_t cap_, size_t ksz_) {
        cap = cap_; ksz = ksz_; mask = cap - 1;
        keys.assign(cap, 0); kbuf.assign(cap * ksz, 0);
    }
    inline const uint8_t * kb(size_t p) const { return &kbuf[p * ksz]; }
    inline bool eq(size_t p, uint64_t h, const uint8_t * k) const {
        return keys[p] == h && memcmp(kb(p), k, ksz) == 0;
    }
};

static inline uint64_t splat(uint8_t b) { return UINT64_C(0x0101010101010101) * b; }
static inline uint64_t sw_match(uint64_t g, uint8_t b) {
    uint64_t x = g ^ splat(b);
    return (x - splat(1)) & ~x & splat(0x80);
}

// ---------------- linear probing ----------------
struct Linear {
    Store s;
    std::vector<uint8_t> st;  // 0 empty, 1 tomb, 2 live
    size_t size = 0, tombs = 0;
    bool prefetch;

    void init(size_t cap, size_t ksz, bool pf) {
        s.init(cap, ksz); st.assign(cap, 0);
        size = tombs = 0; prefetch = pf;
    }
    bool insert(const uint8_t * k, uint64_t h) {
        size_t p = h & s.mask, first_tomb = (size_t)-1;
        for (;;) {
            if (prefetch) __builtin_prefetch(&s.keys[(p + 8) & s.mask], 1, 1);
            if (st[p] == 0) {
                size_t q = (first_tomb != (size_t)-1) ? first_tomb : p;
                if (first_tomb != (size_t)-1) tombs--;
                memcpy(s.kb(q), k, s.ksz); s.keys[q] = h; st[q] = 2; size++;
                return true;
            }
            if (st[p] == 1) { if (first_tomb == (size_t)-1) first_tomb = p; }
            else if (s.eq(p, h, k)) return false;
            p = (p + 1) & s.mask;
        }
    }
    size_t find(const uint8_t * k, uint64_t h) const {
        size_t p = h & s.mask, probes = 1;
        if (prefetch) __builtin_prefetch(&s.keys[p], 0, 1);
        for (;;) {
            if (prefetch) __builtin_prefetch(&s.keys[(p + 8) & s.mask], 0, 1);
            if (st[p] == 0) return probes;
            if (st[p] == 2 && s.eq(p, h, k)) return probes;
            p = (p + 1) & s.mask; probes++;
        }
    }
    void del(const uint8_t * k, uint64_t h) {
        size_t p = h & s.mask;
        for (;;) {
            if (st[p] == 0) return;
            if (st[p] == 2 && s.eq(p, h, k)) { st[p] = 1; size--; tombs++; return; }
            p = (p + 1) & s.mask;
        }
    }
};

// ---------------- Robin Hood + backward shift ----------------
struct RobinHood {
    Store s;
    std::vector<uint8_t> st;
    size_t size = 0;

    void init(size_t cap, size_t ksz) {
        s.init(cap, ksz); st.assign(cap, 0); size = 0;
    }
    inline size_t dist(size_t p, uint64_t h) const {
        return (p - (h & s.mask)) & s.mask;
    }
    bool insert(const uint8_t * k, uint64_t h) {
        size_t p = h & s.mask, d = 0;
        uint64_t cur_h = h;
        std::vector<uint8_t> cur(k, k + s.ksz);
        for (;;) {
            if (st[p] == 0) {
                memcpy(s.kb(p), cur.data(), s.ksz); s.keys[p] = cur_h; st[p] = 1; size++;
                return true;
            }
            if (s.eq(p, cur_h, cur.data())) return false;
            size_t dslot = dist(p, s.keys[p]);
            if (dslot < d) {  // Robin Hood: swap
                std::swap(s.keys[p], cur_h);
                std::swap_ranges(s.kb(p), s.kb(p) + s.ksz, cur.begin());
                d = dslot;
            }
            p = (p + 1) & s.mask; d++;
        }
    }
    size_t find(const uint8_t * k, uint64_t h) const {
        size_t p = h & s.mask, d = 0, probes = 1;
        for (;;) {
            if (st[p] == 0) return probes;
            if (s.eq(p, h, k)) return probes;
            if (dist(p, s.keys[p]) < d) return probes;  // would have been placed earlier
            p = (p + 1) & s.mask; d++; probes++;
        }
    }
    void del(const uint8_t * k, uint64_t h) {
        size_t p = h & s.mask;
        for (;;) {
            if (st[p] == 0) return;
            if (s.eq(p, h, k)) break;
            p = (p + 1) & s.mask;
        }
        // backward shift
        for (;;) {
            size_t q = (p + 1) & s.mask;
            if (st[q] == 0 || dist(q, s.keys[q]) == 0) { st[p] = 0; size--; return; }
            s.keys[p] = s.keys[q];
            memcpy(s.kb(p), s.kb(q), s.ksz);
            st[p] = 1;
            p = q;
        }
    }
};

// ---------------- Swiss-style, scalar ----------------
// ctrl: 0=empty, 1=tomb, 2..255 = h2|2
struct SwissOld {
    Store s;
    std::vector<uint8_t> ctrl;
    size_t size = 0, tombs = 0;

    void init(size_t cap, size_t ksz) {
        s.init(cap, ksz); ctrl.assign(cap, 0); size = tombs = 0;
    }
    inline uint64_t group(size_t p) const {  // byte loads (slow path)
        uint64_t g = 0;
        for (int i = 0; i < 8; i++) g |= (uint64_t)ctrl[(p + i) & s.mask] << (8 * i);
        return g;
    }
    bool insert(const uint8_t * k, uint64_t h) {
        uint8_t h2 = (uint8_t)((h >> 57) | 2);
        size_t p = h & s.mask, first_tomb = (size_t)-1;
        for (;;) {
            uint64_t g = group(p);
            uint64_t m = sw_match(g, h2);
            while (m) {
                size_t q = (p + (__builtin_ctzll(m) / 8)) & s.mask;
                if (s.eq(q, h, k)) return false;
                m &= m - 1;
            }
            uint64_t e = sw_match(g, 0);
            if (e) {
                size_t q = (p + (__builtin_ctzll(e) / 8)) & s.mask;
                if (first_tomb != (size_t)-1) { q = first_tomb; tombs--; }
                memcpy(s.kb(q), k, s.ksz); s.keys[q] = h; ctrl[q] = h2; size++;
                return true;
            }
            if (first_tomb == (size_t)-1) {
                uint64_t t = sw_match(g, 1);
                if (t) first_tomb = (p + (__builtin_ctzll(t) / 8)) & s.mask;
            }
            p = (p + 8) & s.mask;
        }
    }
    size_t find(const uint8_t * k, uint64_t h) const {
        uint8_t h2 = (uint8_t)((h >> 57) | 2);
        size_t p = h & s.mask, probes = 1;
        for (;;) {
            uint64_t g = group(p);
            uint64_t m = sw_match(g, h2);
            while (m) {
                size_t q = (p + (__builtin_ctzll(m) / 8)) & s.mask;
                if (s.eq(q, h, k)) return probes;
                m &= m - 1;
            }
            if (sw_match(g, 0)) return probes;
            p = (p + 8) & s.mask; probes++;
        }
    }
    void del(const uint8_t * k, uint64_t h) {
        uint8_t h2 = (uint8_t)((h >> 57) | 2);
        size_t p = h & s.mask;
        for (;;) {
            uint64_t g = group(p);
            uint64_t m = sw_match(g, h2);
            while (m) {
                size_t q = (p + (__builtin_ctzll(m) / 8)) & s.mask;
                if (s.eq(q, h, k)) { ctrl[q] = 1; size--; tombs++; return; }
                m &= m - 1;
            }
            if (sw_match(g, 0)) return;
            p = (p + 8) & s.mask;
        }
    }
};

// Swiss-style with aligned 64-bit ctrl words (Go swissmap style, no SIMD)
struct SwissSWAR {
    Store s;
    std::vector<uint64_t> ctrlw;  // cap/8 words, byte i of slot j = (ctrlw[j>>3] >> (8*(j&7)))
    size_t size = 0, tombs = 0;

    void init(size_t cap, size_t ksz) {
        s.init(cap, ksz); ctrlw.assign(cap / 8, 0); size = tombs = 0;
    }
    inline uint64_t group(size_t p) const {   // p is group-aligned: one load
        return ctrlw[(p >> 3) & (s.mask >> 3)];
    }
    inline void setc(size_t p, uint8_t c) {
        uint64_t & w = ctrlw[(p >> 3) & (s.mask >> 3)];
        unsigned sh = 8 * (p & 7);
        w = (w & ~(UINT64_C(0xFF) << sh)) | ((uint64_t)c << sh);
    }
    bool insert(const uint8_t * k, uint64_t h) {
        uint8_t h2 = (uint8_t)((h >> 57) | 2);
        size_t p = (h & s.mask) & ~7, first_tomb = (size_t)-1;
        for (;;) {
            uint64_t g = group(p);
            uint64_t m = sw_match(g, h2);
            while (m) {
                size_t q = p + (__builtin_ctzll(m) / 8);
                if (s.eq(q, h, k)) return false;
                m &= m - 1;
            }
            uint64_t e = sw_match(g, 0);
            if (e) {
                size_t q = p + (__builtin_ctzll(e) / 8);
                if (first_tomb != (size_t)-1) { q = first_tomb; tombs--; }
                memcpy(s.kb(q), k, s.ksz); s.keys[q] = h; setc(q, h2); size++;
                return true;
            }
            if (first_tomb == (size_t)-1) {
                uint64_t t = sw_match(g, 1);
                if (t) first_tomb = p + (__builtin_ctzll(t) / 8);
            }
            p = (p + 8) & s.mask;
        }
    }
    size_t find(const uint8_t * k, uint64_t h) const {
        uint8_t h2 = (uint8_t)((h >> 57) | 2);
        size_t p = (h & s.mask) & ~7, probes = 1;
        for (;;) {
            uint64_t g = group(p);
            uint64_t m = sw_match(g, h2);
            while (m) {
                size_t q = p + (__builtin_ctzll(m) / 8);
                if (s.eq(q, h, k)) return probes;
                m &= m - 1;
            }
            if (sw_match(g, 0)) return probes;
            p = (p + 8) & s.mask; probes++;
        }
    }
    void del(const uint8_t * k, uint64_t h) {
        uint8_t h2 = (uint8_t)((h >> 57) | 2);
        size_t p = (h & s.mask) & ~7;
        for (;;) {
            uint64_t g = group(p);
            uint64_t m = sw_match(g, h2);
            while (m) {
                size_t q = p + (__builtin_ctzll(m) / 8);
                if (s.eq(q, h, k)) { setc(q, 1); size--; tombs++; return; }
                m &= m - 1;
            }
            if (sw_match(g, 0)) return;
            p = (p + 8) & s.mask;
        }
    }
};

// ---------------- bench harness ----------------
template <typename T, typename... Args>
static void bench(const char * name, size_t ksz, double load, bool withtombs,
                  const std::vector<uint8_t> & allkeys, Args... args) {
    const size_t cap = 1 << 20;
    size_t total = (size_t)(load * cap);
    size_t live  = withtombs ? (total * 2) / 3 : total;
    size_t tombs = withtombs ? total - live : 0;

    T t; t.init(cap, ksz, args...);

    for (size_t i = 0; i < live + tombs; i++)
        t.insert(&allkeys[i * ksz], eatingHash(&allkeys[i * ksz], ksz, 0));
    for (size_t i = 0; i < tombs; i++)
        t.del(&allkeys[i * ksz], eatingHash(&allkeys[i * ksz], ksz, 0));

    std::vector<size_t> order(live);
    for (size_t i = 0; i < live; i++) order[i] = tombs + ((i * 7919) % live);

    size_t probes_ok = 0, probes_no = 0;
    volatile uint64_t sink = 0;

    auto t0 = std::chrono::steady_clock::now();
    for (int r = 0; r < 3; r++)
        for (size_t i = 0; i < live; i++) {
            size_t idx = order[i];
            size_t pr = t.find(&allkeys[idx * ksz], eatingHash(&allkeys[idx * ksz], ksz, 0));
            probes_ok += pr; sink += pr;
        }
    auto t1 = std::chrono::steady_clock::now();
    double ns_ok = std::chrono::duration<double, std::nano>(t1 - t0).count() / (3.0 * live);

    std::vector<uint8_t> miss(ksz);
    std::mt19937_64 rng(12345);
    t0 = std::chrono::steady_clock::now();
    for (int r = 0; r < 3; r++)
        for (size_t i = 0; i < live; i++) {
            for (size_t j = 0; j < ksz; j++) miss[j] = (uint8_t)rng();
            size_t pr = t.find(miss.data(), eatingHash(miss.data(), ksz, 0));
            probes_no += pr; sink += pr;
        }
    t1 = std::chrono::steady_clock::now();
    double ns_no = std::chrono::duration<double, std::nano>(t1 - t0).count() / (3.0 * live);

    printf("%-11s %4.1f%% %s | ok %5.2f pr %6.1f ns | miss %5.2f pr %6.1f ns\n",
           name, load * 100, withtombs ? "w/tombs" : "clean ",
           (double)probes_ok / (3.0 * live), ns_ok,
           (double)probes_no / (3.0 * live), ns_no);
}

int main() {
    const size_t N = 1 << 21;
    std::mt19937_64 rng(20261007);

    for (size_t ksz : { (size_t)8, (size_t)24 }) {
        std::vector<uint8_t> keys(N * ksz);
        for (auto & b : keys) b = (uint8_t)rng();
        printf("\n===== key %zu B, cap 1M, eatingHash =====\n", ksz);
        for (double lf : { 0.50, 0.75, 0.875 }) {
            for (int wt = 0; wt < 2; wt++) {
                bench<Linear>       ("linear",      ksz, lf, wt, keys, false);
                bench<Linear>       ("linear+pf",   ksz, lf, wt, keys, true);
                bench<SwissOld>     ("swiss8-byte", ksz, lf, wt, keys);
                bench<SwissSWAR>    ("swiss8-swar", ksz, lf, wt, keys);
                if (!wt) bench<RobinHood>("robinhood", ksz, lf, wt, keys);
            }
        }
    }
    return 0;
}

// Speed variants of eatingHash (no SIMD): how to make the ALGORITHM faster.
// v0  = original (serial chain, 2 muls per 8 bytes)
// v1  = 2 parallel lanes (ILP)
// v2  = 4 parallel lanes (ILP, xxHash64-style)
// v3  = 128-bit multiply mix (1 mul per 8 bytes, serial)
// v4  = 4 lanes + 128-bit multiply
// v5  = original with lighter finalization (5 muls instead of 7)
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <chrono>
#include <vector>
#include <random>

static const uint64_t C1 = UINT64_C(0xBABEBEEFBABEBEEF);
static const uint64_t C2 = UINT64_C(0xF00DF00DF00DF00D);
static const uint64_t C3 = UINT64_C(0xBABEBEEFF00DF00D);
static const uint64_t SEED_XOR = UINT64_C(0xCAFECAFECAFECAFE);

static inline uint64_t rotl(uint64_t x, unsigned r) { return (x << r) | (x >> (64 - r)); }

static inline uint64_t mix2(uint64_t h, uint64_t w) {   // 2 muls
    h ^= w;
    h *= C1;
    h ^= h >> 33;
    h *= C2;
    h ^= h >> 29;
    return h;
}
static inline uint64_t mix128(uint64_t h, uint64_t w) { // 1 mul (64x64->128)
    unsigned __int128 p = (unsigned __int128)(h ^ w) * (unsigned __int128)C1;
    h = (uint64_t)p ^ (uint64_t)(p >> 64);
    h ^= h >> 33;
    return h;
}

static inline uint64_t get64(const uint8_t * b) {
    uint64_t v; memcpy(&v, b, 8); return v;
}

// shared tail assembly (little-endian, 0..7 bytes)
static inline uint64_t tail7(const uint8_t * b, size_t n) {
    uint64_t t = 0;
    for (size_t j = 0; j < n; j++) t |= (uint64_t)b[j] << (8 * j);
    return t;
}

// ---------- v0: original ----------
static uint64_t hash_v0(const uint8_t * buf, size_t len, uint64_t seed) {
    size_t rmd = len, i = 0;
    const uint64_t s = seed ^ SEED_XOR;
    uint64_t h = s;
    for (; rmd >= 8; i += 8, rmd -= 8) h = mix2(h, get64(buf + i));
    h = mix2(h, tail7(buf + i, rmd));
    h ^= (uint64_t)len * C1;
    h ^= s * C2;
    h *= C1; h ^= h >> 33; h *= C2; h ^= h >> 29;
    h *= C3; h ^= h >> 31;
    return h;
}

// ---------- v1: 2 lanes ----------
static uint64_t hash_v1(const uint8_t * buf, size_t len, uint64_t seed) {
    size_t rmd = len, i = 0;
    const uint64_t s = seed ^ SEED_XOR;
    uint64_t h0 = s, h1 = rotl(s, 32) + C3;
    for (; rmd >= 16; i += 16, rmd -= 16) {
        h0 = mix2(h0, get64(buf + i));
        h1 = mix2(h1, get64(buf + i + 8));
    }
    for (; rmd >= 8; i += 8, rmd -= 8) h0 = mix2(h0, get64(buf + i));
    h0 = mix2(h0, tail7(buf + i, rmd) ^ rotl(h1, 27));
    h ^= 0; // no-op keeps structure clear
    h0 ^= (uint64_t)len * C1;
    h0 ^= s * C2;
    h0 *= C1; h0 ^= h0 >> 33; h0 *= C2; h0 ^= h0 >> 29;
    h0 *= C3; h0 ^= h0 >> 31;
    return h0;
}

// ---------- v2: 4 lanes ----------
static uint64_t hash_v2(const uint8_t * buf, size_t len, uint64_t seed) {
    size_t rmd = len, i = 0;
    const uint64_t s = seed ^ SEED_XOR;
    uint64_t h0 = s, h1 = s + C1, h2 = s + C2, h3 = s + C3;
    for (; rmd >= 32; i += 32, rmd -= 32) {
        h0 = mix2(h0, get64(buf + i));
        h1 = mix2(h1, get64(buf + i + 8));
        h2 = mix2(h2, get64(buf + i + 16));
        h3 = mix2(h3, get64(buf + i + 24));
    }
    unsigned lane = 0;
    for (; rmd >= 8; i += 8, rmd -= 8, lane = (lane + 1) & 3) {
        uint64_t w = get64(buf + i);
        switch (lane) {
        case 0: h0 = mix2(h0, w); break;
        case 1: h1 = mix2(h1, w); break;
        case 2: h2 = mix2(h2, w); break;
        default: h3 = mix2(h3, w); break;
        }
    }
    uint64_t t = tail7(buf + i, rmd);
    switch (lane) {
    case 0: h0 = mix2(h0, t); break;
    case 1: h1 = mix2(h1, t); break;
    case 2: h2 = mix2(h2, t); break;
    default: h3 = mix2(h3, t); break;
    }
    uint64_t h = mix2(h0, rotl(h1, 21)) ^ mix2(h2, rotl(h3, 42));
    h ^= (uint64_t)len * C1;
    h ^= s * C2;
    h *= C3; h ^= h >> 31;
    return h;
}

// ---------- v3: 128-bit mul, serial ----------
static uint64_t hash_v3(const uint8_t * buf, size_t len, uint64_t seed) {
    size_t rmd = len, i = 0;
    const uint64_t s = seed ^ SEED_XOR;
    uint64_t h = s;
    for (; rmd >= 8; i += 8, rmd -= 8) h = mix128(h, get64(buf + i));
    h = mix128(h, tail7(buf + i, rmd));
    h ^= (uint64_t)len * C1;
    h ^= s * C2;
    h *= C1; h ^= h >> 33; h *= C2; h ^= h >> 29;
    h *= C3; h ^= h >> 31;
    return h;
}

// ---------- v4: 4 lanes + 128-bit mul ----------
static uint64_t hash_v4(const uint8_t * buf, size_t len, uint64_t seed) {
    size_t rmd = len, i = 0;
    const uint64_t s = seed ^ SEED_XOR;
    uint64_t h0 = s, h1 = s + C1, h2 = s + C2, h3 = s + C3;
    for (; rmd >= 32; i += 32, rmd -= 32) {
        h0 = mix128(h0, get64(buf + i));
        h1 = mix128(h1, get64(buf + i + 8));
        h2 = mix128(h2, get64(buf + i + 16));
        h3 = mix128(h3, get64(buf + i + 24));
    }
    unsigned lane = 0;
    for (; rmd >= 8; i += 8, rmd -= 8, lane = (lane + 1) & 3) {
        uint64_t w = get64(buf + i);
        switch (lane) {
        case 0: h0 = mix128(h0, w); break;
        case 1: h1 = mix128(h1, w); break;
        case 2: h2 = mix128(h2, w); break;
        default: h3 = mix128(h3, w); break;
        }
    }
    uint64_t t = tail7(buf + i, rmd);
    switch (lane) {
    case 0: h0 = mix128(h0, t); break;
    case 1: h1 = mix128(h1, t); break;
    case 2: h2 = mix128(h2, t); break;
    default: h3 = mix128(h3, t); break;
    }
    uint64_t h = mix128(h0, rotl(h1, 21)) ^ mix128(h2, rotl(h3, 42));
    h ^= (uint64_t)len * C1;
    h ^= s * C2;
    h *= C3; h ^= h >> 31;
    return h;
}

// ---------- v5: original loop, lighter finalization ----------
static uint64_t hash_v5(const uint8_t * buf, size_t len, uint64_t seed) {
    size_t rmd = len, i = 0;
    const uint64_t s = seed ^ SEED_XOR;
    uint64_t h = s;
    for (; rmd >= 8; i += 8, rmd -= 8) h = mix2(h, get64(buf + i));
    h = mix2(h, tail7(buf + i, rmd));
    h ^= ((uint64_t)len * C1) ^ (s * C2);
    h *= C3; h ^= h >> 31;
    return h;
}

// ---------------- bench ----------------
using HFn = uint64_t (*)(const uint8_t *, size_t, uint64_t);

static void bench(const char * name, HFn fn, const std::vector<uint8_t> & buf,
                  size_t len, int iters) {
    volatile uint64_t sink = 0;
    uint64_t seed = 0x0123456789ABCDEF;
    // warmup
    for (int i = 0; i < 1000; i++) sink += fn(buf.data(), len, seed + i);
    auto t0 = std::chrono::steady_clock::now();
    for (int i = 0; i < iters; i++) sink += fn(buf.data(), len, seed + i);
    auto t1 = std::chrono::steady_clock::now();
    double ns = std::chrono::duration<double, std::nano>(t1 - t0).count() / iters;
    if (len >= 1024) {
        printf("%-6s %7zu B  %8.2f ns/hash  %6.2f B/cycle (@3.5GHz)\n",
               name, len, ns, len / (ns * 3.5));
    } else {
        printf("%-6s %7zu B  %8.2f ns/hash\n", name, len, ns);
    }
}

int main() {
    std::mt19937_64 rng(42);
